const $=s=>document.querySelector(s), KEY='buildday-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateKey(), uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const roadmap=[['Personal productivity app','Build your own daily workspace','3–4 weeks'],['Portfolio website','Give your work a home on the web','1–2 weeks'],['Service business website','Turn visitors into customer inquiries','1–2 weeks'],['Restaurant website','A beautiful menu, made for mobile','1–2 weeks'],['Property listing website','Help people find their next space','2–3 weeks'],['Appointment booking app','Make booking a service effortless','3–5 weeks'],['Quote & invoice builder','Bring clarity to business paperwork','2–4 weeks'],['Client project portal','Keep clients and projects in sync','3–5 weeks'],['Inventory & sales tracker','Help a small business stay organized','3–5 weeks'],['Freelancer CRM','Turn conversations into opportunities','3–4 weeks'],['Service business SaaS','A workspace for a service business','6–8 weeks'],['Content approval SaaS','Make creative collaboration simpler','6–8 weeks']];
const milestones=[['Define scope',10,'Write down the user, problem, pages, and required features.'],['Design',20,'Prepare the mobile and desktop layouts.'],['Build core features',40,'Make the required workflows function.'],['Test & improve',20,'Check main workflows, mobile layouts, and error states.'],['Publish & document',10,'Publish a live demo and write your case study.']];
function fresh(){return {version:1,tasks:[],projects:roadmap.map((p,i)=>({id:String(i+1),title:p[0],description:p[1],duration:p[2],milestones:[false,false,false,false,false]})),focus:'1',logs:[],leads:[],ready:[false,false,false,false],plannedDays:5,notified:[]}}
let state=fresh(), loadError=false;try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);validate(data);state=data}}catch(e){loadError=true}
function validate(d){if(!d||d.version!==1||!Array.isArray(d.tasks)||!Array.isArray(d.projects)||!Array.isArray(d.logs)||!Array.isArray(d.leads)||!Array.isArray(d.ready)||!Array.isArray(d.notified)||d.projects.length<1||!Number.isInteger(d.plannedDays)||d.plannedDays<1||d.plannedDays>7)throw Error('Invalid backup');if(d.projects.some(p=>typeof p.id!=='string'||typeof p.title!=='string'||!Array.isArray(p.milestones)||p.milestones.length!==5||p.milestones.some(m=>typeof m!=='boolean')))throw Error('Invalid projects');if(d.tasks.some(t=>typeof t.id!=='string'||typeof t.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||!Array.isArray(t.days)||!Array.isArray(t.completed)||!['none','daily','weekdays'].includes(t.repeat)))throw Error('Invalid tasks');if(d.logs.some(l=>typeof l.date!=='string'||typeof l.note!=='string')||d.leads.some(l=>typeof l.id!=='string'||typeof l.name!=='string'))throw Error('Invalid records');}
let view=location.hash.slice(1)||'today',filter='All',calendarOffset=0;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('Could not save. Export a backup before closing this page.');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',6000)}
function pct(p){return p.milestones.reduce((n,v,i)=>n+(v?milestones[i][1]:0),0)}
function activeDates(){return new Set([...state.logs.map(l=>l.date),...state.tasks.filter(t=>t.project).flatMap(t=>t.completed.map(c=>c.at))])}
function weekDates(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(d.getDate()+i);return dateKey(n)})}
function occurrences(){const out=[];for(const t of state.tasks){if(t.repeat==='none'){out.push({t,date:t.date});continue}let d=new Date(t.date+'T12:00:00'),end=new Date(today()+'T12:00:00');for(let guard=0;d<=end&&guard<3660;guard++,d.setDate(d.getDate()+1)){if(t.repeat==='daily'||t.days.includes(d.getDay()))out.push({t,date:dateKey(d)})}}return out}
const isDone=o=>o.t.completed.some(c=>c.date===o.date);
const daily=()=>occurrences().filter(o=>o.date===today());
function track(n){return `<div class="track"><i style="width:${n}%"></i></div>`}
function heading(eyebrow,title,sub,button=''){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
function taskRow(o){const {t,date}=o,done=isDone(o);return `<div class="task ${done?'done':''}"><input class="check" type="checkbox" aria-label="Complete ${esc(t.title)}" data-toggle="${t.id}" data-date="${date}" ${done?'checked':''}><div class="task-copy"><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span>${esc(t.category)}</span><span><i class="priority-dot ${t.priority==='High'?'high':''}"></i>${esc(t.priority)}</span>${date<today()&&!done?`<span class="overdue">Overdue · ${date}</span>`:''}${t.time?`<span>◷ ${esc(t.time)}</span>`:''}${t.repeat!=='none'?'<span>↻ Repeats</span>':''}${t.project?`<span>↗ ${esc(state.projects.find(p=>p.id===t.project)?.title||'Project')}</span>`:''}</div></div><button class="edit" data-edit-task="${t.id}" aria-label="Edit ${esc(t.title)}">···</button></div>`}
function render(){if(!['today','projects','activity','clients'].includes(view))view='today';const labels={today:'Today',projects:'Projects',activity:'Activity',clients:'Client Journey'},icons={today:'◫',projects:'▦',activity:'◷',clients:'↗'};$('#nav').innerHTML=Object.keys(labels).map(k=>`<a href="#${k}" class="${view===k?'active':''}"><span>${icons[k]}</span>${labels[k]}${k==='projects'?'<b>'+state.projects.length+'</b>':''}</a>`).join('');$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${labels[view]}`;$('#app').innerHTML=({today:renderToday,projects:renderProjects,activity:renderActivity,clients:renderClients}[view])();}
function renderToday(){const ds=daily(),done=ds.filter(isDone).length,progress=ds.length?Math.round(done/ds.length*100):0,active=activeDates(),week=weekDates(),days=week.filter(d=>active.has(d)).length,p=state.projects.find(p=>p.id===state.focus)||state.projects[0];const all=occurrences().filter(o=>o.date<=today()&&(!isDone(o)||o.date===today())).sort((a,b)=>Number(isDone(a))-Number(isDone(b))||a.date.localeCompare(b.date));const visible=filter==='Upcoming'?state.tasks.filter(t=>t.date>today()).map(t=>({t,date:t.date})):filter==='Completed'?occurrences().filter(isDone).sort((a,b)=>b.date.localeCompare(a.date)):all.filter(o=>filter==='All'||o.t.category===filter),priorities=all.filter(o=>!isDone(o)&&o.t.priority==='High').slice(0,3);const next=milestones.find((m,i)=>!p.milestones[i]);return heading(new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}),`Make today count<span style="color:var(--purple)">.</span>`,'A little focus. A little progress. One step closer.',`<button class="primary" data-add-task>＋ Add task</button>`)+`<div class="stats"><div class="stat"><div class="stat-top">Today’s progress <span class="stat-icon">◫</span></div><div class="stat-value">${done}<small> / ${ds.length} tasks</small></div>${track(progress)}<div class="stat-note">${progress}% complete · You’ve got this</div></div><div class="stat"><div class="stat-top">Building consistency <span class="stat-icon">◷</span></div><div class="stat-value">${days}<small> / ${state.plannedDays} planned days</small></div><div class="stat-note" style="margin-top:20px">${Math.min(100,Math.round(days/state.plannedDays*100))}% of your weekly goal</div></div><div class="stat"><div class="stat-top">Your building journey <span class="stat-icon">↗</span></div><div class="stat-value">${state.projects.filter(p=>pct(p)===100).length}<small> / ${state.projects.length} projects shipped</small></div><div class="stat-note" style="margin-top:20px">From first idea to first client</div></div></div><div class="columns"><div><section class="panel"><div class="panel-head"><h2><span>✦</span> Your top priorities</h2><small>MAKE SPACE FOR WHAT MATTERS</small></div>${priorities.length?priorities.map(taskRow).join(''):'<div class="empty"><div class="empty-symbol">◎</div><strong>What would make today a good day?</strong>Add up to three high-priority tasks to focus on.</div>'}</section>`+'<section class="panel"><div class="panel-head"><h2>Today’s tasks <small> · '+all.length+'</small></h2><small>'+done+' completed today</small></div><div class="tabs">'+['All','Work','Personal','Upcoming','Completed'].map(f=>`<button data-filter="${f}" class="${filter===f?'selected':''}">${f}</button>`).join('')+'</div>'+ (visible.length?visible.map(taskRow).join(''):'<div class="empty"><strong>A clear day, ready for your plans.</strong>Add your first task and take it one step at a time.</div>')+'<button class="add-row" data-add-task>＋ Add a new task</button></section></div><div><section class="panel"><div class="panel-head"><h2>Your focus project</h2><span class="pill">'+(pct(p)===100?'Completed':'Learning by building')+'</span></div><div class="focus-art"><span>&lt;/&gt;</span></div><div class="panel-body"><div class="eyebrow">PROJECT '+p.id.padStart(2,'0')+' OF '+state.projects.length+'</div><h2 class="focus-title">'+esc(p.title)+'</h2><p class="muted">'+esc(p.description)+'</p><div class="between"><small class="muted">Project progress</small><strong style="color:var(--purple)">'+pct(p)+'%</strong></div>'+track(pct(p))+'<p class="muted">Next: '+(next?next[0]:'Celebrate your finished project')+'</p><button class="secondary" style="width:100%" data-project="'+p.id+'">Continue building <span style="float:right">↗</span></button></div></section><section class="panel"><div class="panel-head"><h2>This week</h2><small>'+days+' active days</small></div><div class="panel-body"><div class="week">'+week.map((d,i)=>`<div class="day ${active.has(d)?'active':''} ${d===today()?'current':''}"><b>${active.has(d)?'✓':new Date(d+'T12:00:00').getDate()}</b>${['M','T','W','T','F','S','S'][i]}</div>`).join('')+'</div></div></section><section class="panel reflection"><div class="panel-head"><h2>✧ A moment to reflect</h2></div><div class="panel-body"><p class="muted">What did you build or learn today?<br>Small wins deserve to be remembered.</p><button class="text-link" data-log>Add your daily reflection →</button></div></section></div></div>'}
function renderProjects(){return heading('YOUR LEARNING ROADMAP','Build something real.',`${state.projects.length} practical projects. One focused step at a time.`, '<button class="primary" data-new-project>＋ New project</button>')+`<div class="project-grid">${state.projects.map(p=>`<article class="panel project-card">${projectCover(p)}<div class="between"><span class="project-number">${p.id.padStart(2,'0')}</span>${p.id===state.focus?'<span class="pill">Current focus</span>':`<span class="muted">${esc(p.duration)}</span>`}</div><h2>${esc(p.title)}</h2><p class="muted">${esc(p.description)}</p><div class="between"><small class="muted">${p.milestones.filter(Boolean).length} / 5 milestones</small><span>${pct(p)}%</span></div>${track(pct(p))}<div class="project-actions"><button class="text-link" data-project="${p.id}">Open project ↗</button>${projectWebsiteIcon(p)}</div><button class="text-link" data-project-media="${p.id}">Edit image & website</button></article>`).join('')}</div>`}
function renderActivity(){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+calendarOffset);const active=activeDates(),offset=(d.getDay()+6)%7,count=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return heading('YOUR PROGRESS, DAY BY DAY','Show up. Build. Repeat.','A record of your effort, your lessons, and your small wins.',`<button class="primary" data-log>＋ Log a session</button>`)+`<div class="columns"><section class="panel"><div class="panel-head"><h2>${d.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h2><div><button class="icon-button" data-month="-1" aria-label="Previous month">‹</button> <button class="icon-button" data-month="1" aria-label="Next month">›</button></div></div><div class="panel-body"><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="calendar-label">${x}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const key=dateKey(new Date(d.getFullYear(),d.getMonth(),i+1,12));return `<div class="calendar-day ${active.has(key)?'active':''} ${key===today()?'current':''}">${i+1}${active.has(key)?'<small>✦ Built today</small>':''}</div>`}).join('')}</div><p class="muted">An active day includes a completed project task or a logged building session.</p></div></section><section class="panel"><div class="panel-head"><h2>Building journal</h2><small>${state.logs.length} entries</small></div><div class="panel-body">${state.logs.length?state.logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(l=>`<div class="log"><small>${esc(l.date)} · ${Number(l.minutes)||0} minutes</small><div>${esc(l.note)}</div></div>`).join(''):'<div class="empty"><strong>Your story starts here.</strong>Record a session to mark your first active day.</div>'}</div></section></div>`}
function renderClients(){const items=['Publish my portfolio with a clear service offer','Finish two relevant demo projects','Write a case study with screenshots','Prepare my introductory message and proposal'];return heading('FROM BUILDER TO BUSINESS','Your first client starts here.','Prepare your work, start conversations, and follow through.',`<button class="primary" data-add-lead>＋ Add a lead</button>`)+`<div class="columns"><section class="panel"><div class="panel-head"><h2>Conversations & opportunities</h2><small>${state.leads.length} leads</small></div><div class="panel-body">${state.leads.length?state.leads.map(l=>`<div class="lead"><div class="between"><strong>${esc(l.name)}</strong><button class="text-link" data-lead="${l.id}">Edit</button></div><p class="muted">${esc(l.notes)}</p><div class="between"><span class="pill">${esc(l.stage)}</span><small class="${l.followup&&l.followup<today()?'overdue':'muted'}">${l.followup?'Follow up: '+esc(l.followup):'No follow-up scheduled'}</small></div></div>`).join(''):'<div class="empty"><div class="empty-symbol">↗</div><strong>Every client starts with a conversation.</strong>Add a business you’d like to help. Track your next step here.</div>'}</div></section><section class="panel"><div class="panel-head"><h2>Get client-ready</h2><span class="pill">${state.ready.filter(Boolean).length} / 4</span></div><div class="panel-body">${items.map((s,i)=>`<label class="readiness"><input type="checkbox" data-ready="${i}" ${state.ready[i]?'checked':''}><span>${s}</span></label>`).join('')}<p class="muted">Readiness is a checklist, not a prediction of when you’ll win a client.</p></div></section></div>`}
function modal(html,onSubmit){$('#form').innerHTML=html;$('#form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.target))};$('#dialog').showModal()}
const actions=(saveText='Save',remove='')=>`<div class="form-actions">${remove}<button type="button" class="plain" data-close>Cancel</button><button class="primary" type="submit">${saveText}</button></div>`;
function taskForm(id){const t=state.tasks.find(t=>t.id===id)||{title:'',category:'Work',priority:'Medium',date:today(),time:'',repeat:'none',days:[1,2,3,4,5],project:'',notes:''};modal(`<div class="between"><h2>${id?'Edit task':'Make a little progress'}</h2><button type="button" class="plain" data-close aria-label="Close">✕</button></div><p>Give your next step a name. Keep it small enough for one session.</p><label>Task title<input name="title" required maxlength="180" value="${esc(t.title)}" placeholder="What would you like to get done?" autofocus></label><div class="form-grid"><label>Category<select name="category">${['Work','Personal'].map(s=>`<option ${t.category===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Priority<select name="priority">${['Low','Medium','High'].map(s=>`<option ${t.priority===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Due date / repeat start<input type="date" name="date" required value="${t.date}"></label><label>Reminder time<input type="time" name="time" value="${esc(t.time)}"></label></div><p>Reminders appear in this app while it is open.</p><label>Project<select name="project"><option value="">No project</option>${state.projects.map(p=>`<option value="${p.id}" ${t.project===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><label>Repeat<select name="repeat"><option value="none" ${t.repeat==='none'?'selected':''}>Does not repeat</option><option value="daily" ${t.repeat==='daily'?'selected':''}>Every day</option><option value="weekdays" ${t.repeat==='weekdays'?'selected':''}>Selected weekdays</option></select></label><div class="weekday-inputs">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${t.days.includes(i)?'checked':''}>${d}</label>`).join('')}</div><label>Notes<textarea name="notes" maxlength="2000">${esc(t.notes)}</textarea></label>${id?'<p>Edits affect this task’s schedule. Deleting removes the task and its completion history.</p>':''}${actions('Save task',id?`<button type="button" class="plain danger" data-delete-task="${id}">Delete</button>`:'')}`,fd=>{const title=fd.get('title').trim(),days=fd.getAll('days').map(Number);if(!title)return toast('Give your task a title.');if(fd.get('repeat')==='weekdays'&&!days.length)return toast('Choose at least one weekday.');const item={id:id||uid(),title,category:fd.get('category'),priority:fd.get('priority'),date:fd.get('date'),time:fd.get('time'),project:fd.get('project'),repeat:fd.get('repeat'),days,notes:fd.get('notes'),completed:t.completed||[]};if(id)state.tasks[state.tasks.findIndex(x=>x.id===id)]=item;else state.tasks.push(item);save();$('#dialog').close();render();toast('Task saved. One step at a time.')})}
function projectForm(id){const p=state.projects.find(p=>p.id===id);modal(`<div class="eyebrow">PROJECT ${p.id.padStart(2,'0')} · ${esc(p.duration)}</div><h2 style="margin-top:12px">${esc(p.title)}</h2>${p.custom?`<button type="button" class="text-link" data-edit-project="${p.id}">Edit project details ↗</button>`:''}<p>${esc(p.description)}. Complete each milestone when its deliverable is ready.</p><div class="between"><span>Project progress</span><strong>${pct(p)}%</strong></div>${track(pct(p))}${milestones.map((m,i)=>`<label class="milestone"><input class="check" type="checkbox" name="milestone" value="${i}" ${p.milestones[i]?'checked':''}><span>${m[0]}<small class="muted" style="display:block">${m[2]}</small></span><b>${m[1]}%</b></label>`).join('')}<label><input type="checkbox" name="focus" ${state.focus===id?'checked':''}> Make this my focus project</label>${actions('Save progress')}`,fd=>{p.milestones=milestones.map((_,i)=>fd.getAll('milestone').includes(String(i)));if(fd.has('focus'))state.focus=id;save();$('#dialog').close();render();toast('Project progress updated.')})}
function logForm(){modal(`<h2>Every small win counts.</h2><p>Record what you built, learned, or worked through.</p><div class="form-grid"><label>Date<input type="date" name="date" required max="${today()}" value="${today()}"></label><label>Minutes spent<input type="number" name="minutes" min="1" max="1440" value="120" required></label></div><label>Your reflection<textarea name="note" placeholder="Today I built…" maxlength="3000" required></textarea></label>${actions('Save session')}`,fd=>{if(!fd.get('note').trim())return toast('Write a short reflection.');state.logs.push({id:uid(),date:fd.get('date'),minutes:Number(fd.get('minutes')),note:fd.get('note').trim()});save();$('#dialog').close();render();toast('Session recorded. That’s progress.')})}
function leadForm(id){const l=state.leads.find(l=>l.id===id)||{name:'',notes:'',stage:'Prospect',followup:''};modal(`<h2>${id?'Update opportunity':'Start a conversation'}</h2><label>Business / contact<input name="name" required maxlength="150" value="${esc(l.name)}"></label><label>Stage<select name="stage">${['Prospect','Contacted','Replied','Call scheduled','Proposal sent','Won','Closed'].map(s=>`<option ${l.stage===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Follow-up date<input type="date" name="followup" value="${esc(l.followup)}"></label><label>Notes<textarea name="notes" maxlength="2000">${esc(l.notes)}</textarea></label>${actions('Save lead',id?`<button type="button" class="plain danger" data-delete-lead="${id}">Delete</button>`:'')}`,fd=>{if(!fd.get('name').trim())return;const item={id:id||uid(),name:fd.get('name').trim(),stage:fd.get('stage'),followup:fd.get('followup'),notes:fd.get('notes')};if(id)state.leads[state.leads.findIndex(l=>l.id===id)]=item;else state.leads.push(item);save();$('#dialog').close();render()})}
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`buildday-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported.')}
function settings(){modal(`<h2>Your workspace</h2><p>Your data is saved in this browser. Export regularly to keep a backup or move to another device.</p><label>Planned building days per week<input name="plannedDays" type="number" min="1" max="7" value="${state.plannedDays}" required></label><p>Dates and reminders use your device’s local timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</p><button type="button" class="secondary" data-export>↓ Export backup</button><label>Restore backup (replaces current data)<input type="file" id="import-file" accept="application/json,.json"></label><p>Import only a BuildDay backup you trust. You’ll confirm before replacing your current data.</p>${actions('Save preferences')}`,fd=>{state.plannedDays=Number(fd.get('plannedDays'));save();$('#dialog').close();render()})}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if('close'in d)$('#dialog').close();if('addTask'in d)taskForm();if(d.editTask)taskForm(d.editTask);if(d.project)projectForm(d.project);if('filter'in d){filter=d.filter;render()}if('log'in d)logForm();if('month'in d){calendarOffset+=Number(d.month);render()}if('addLead'in d)leadForm();if(d.lead)leadForm(d.lead);if(d.deleteTask&&confirm('Delete this task and its completion history?')){state.tasks=state.tasks.filter(t=>t.id!==d.deleteTask);save();$('#dialog').close();render()}if(d.deleteLead&&confirm('Delete this lead?')){state.leads=state.leads.filter(l=>l.id!==d.deleteLead);save();$('#dialog').close();render()}if(el.id==='settings')settings();if(el.id==='export'||'export'in d)exportData()});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.toggle){const t=state.tasks.find(t=>t.id===el.dataset.toggle),date=el.dataset.date;t.completed=t.completed.filter(c=>c.date!==date);if(el.checked)t.completed.push({date,at:today()});save();render()}if('ready'in el.dataset){state.ready[Number(el.dataset.ready)]=el.checked;save();render()}if(el.id==='import-file'&&el.files[0]){try{if(el.files[0].size>5e6)throw Error('Too large');const incoming=JSON.parse(await el.files[0].text());validate(incoming);if(confirm('Replace your current workspace with this backup? Export your current data first if you need to keep it.')){state=incoming;save();$('#dialog').close();render();toast('Backup restored.')}}catch(err){toast('This backup is invalid or too large. Your current data was kept.')}el.value=''}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);render()});
let lastDay=today();function reminders(){if(today()!==lastDay){lastDay=today();render()}const now=new Date(),time=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;const due=occurrences().filter(o=>!isDone(o)&&o.t.time&&(o.date<today()||o.date===today()&&o.t.time<=time)&&!state.notified.includes(o.t.id+o.date+o.t.time));if(due.length){toast(`Reminder: ${due.slice(0,3).map(o=>o.t.title).join(' · ')}${due.length>3?' + more':''}`);state.notified.push(...due.map(o=>o.t.id+o.date+o.t.time));save()}}
// Only dismiss when both ends of the gesture are on the backdrop.
const appDialog=$('#dialog');
let backdropPress=false;
function isDialogBackdrop(event){
  const rect=appDialog.getBoundingClientRect();
  return event.target===appDialog && (event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom);
}
appDialog.addEventListener('pointerdown',event=>{backdropPress=isDialogBackdrop(event);});
appDialog.addEventListener('click',event=>{if(backdropPress&&isDialogBackdrop(event))appDialog.close();backdropPress=false;});
appDialog.addEventListener('pointercancel',()=>{backdropPress=false;});
appDialog.addEventListener('close',()=>{backdropPress=false;});
render();if(loadError)toast('Saved data could not be read. Import a valid backup before making changes.');setInterval(reminders,30000);setTimeout(reminders,1500);

function safeProjectUrl(value){try{const u=new URL(value);return ["http:","https:"].includes(u.protocol)&&!u.username&&!u.password;}catch{return false;}}
function projectCover(p){if(!safeProjectUrl(p.imageUrl))return "";return `<div class="project-cover">${safeProjectUrl(p.imageUrl)?`<a href="${esc(p.imageUrl)}" target="_blank" rel="noopener noreferrer" aria-label="View image for ${esc(p.title)}"><img src="${esc(p.imageUrl)}" alt="${esc(p.title)} preview" loading="lazy" referrerpolicy="no-referrer"></a>`:"<span>No project image yet</span>"}</div>`;}

function projectWebsiteIcon(p){
 const icon='<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 3h6v6M10 14 21 3"/><path d="M21 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5"/></svg>';
 return safeProjectUrl(p.siteUrl)?'<a class="website-view-icon" href="'+esc(p.siteUrl)+'" target="_blank" rel="noopener noreferrer" title="View website" aria-label="View website for '+esc(p.title)+'">'+icon+'</a>':'<button type="button" class="website-view-icon" data-project-media="'+p.id+'" title="Add website link" aria-label="Add website link for '+esc(p.title)+'">'+icon+'</button>';
}
